*** Begin Patch
*** Add File: public/styles.css
+@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap');
+
+:root {
+  color: #23362f;
+  background: #f8f6f1;
+  font-family: 'DM Sans', Arial, sans-serif;
+  font-synthesis: none;
+  -webkit-font-smoothing: antialiased;
+}
+
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body { margin: 0; }
+button, input, textarea { font: inherit; }
+button { cursor: pointer; }
+a { color: inherit; text-decoration: none; }
+:focus-visible { outline: 3px solid #c77d58; outline-offset: 4px; }
+
+.site-shell { max-width: 1512px; margin: 0 auto; padding: 0 56px; }
+.site-header { display: flex; align-items: center; justify-content: space-between; height: 92px; border-bottom: 1px solid #e8e5dd; }
+.brand { display: inline-flex; align-items: center; gap: 12px; font: 32px/1 'DM Serif Display', Georgia, serif; letter-spacing: -.06em; white-space: nowrap; }
+.brand-period { color: #c67854; }
+.brand-mark { position: relative; width: 30px; height: 30px; display: inline-flex; gap: 2px; padding: 6px 4px; border-radius: 7px; background: #233a32; transform: rotate(-7deg); }
+.brand-mark span { display: block; width: 10px; border: 1.5px solid #f3eee3; border-radius: 2px 1px 1px 2px; transform: skewY(10deg); }
+.brand-mark span + span { border-radius: 1px 2px 2px 1px; transform: skewY(-10deg); }
+.top-nav { display: flex; align-items: center; gap: 34px; font-size: 13px; font-weight: 700; }
+.top-nav > a:first-child { padding: 8px 0; }
+.top-nav > a:first-child:hover, .top-nav > a[aria-current=\"page\"] { color: #b86e4d; }
+.nav-add { display: inline-flex; align-items: center; gap: 8px; padding: 12px 17px; border: 1px solid #deded5; border-radius: 6px; background: #fffefa; transition: background .2s, transform .2s; }
+.nav-add:hover { background: #f1ede5; transform: translateY(-2px); }
+.nav-add span { font-size: 18px; line-height: 10px; font-weight: 400; }
+
+.hero { position: relative; display: grid; grid-template-columns: 1.08fr .92fr; min-height: 405px; margin-top: 26px; overflow: hidden; border-radius: 9px; background: #243c33; color: #fffdf6; }
+.hero::before { position: absolute; inset: 0; content: ''; background: radial-gradient(circle at 77% 57%, #3f5a4b 0, transparent 44%); pointer-events: none; }
+.hero-content { position: relative; z-index: 1; padding: 70px 20px 64px 71px; }
+.eyebrow { margin: 0; color: #a2775f; font-size: 10px; font-weight: 700; line-height: 1.4; letter-spacing: .18em; }
+.hero-eyebrow { display: flex; align-items: center; gap: 10px; color: #ddae86; }
+.eyebrow-line { width: 19px; height: 1px; background: currentColor; }
+h1, h2, h3, p { margin-top: 0; }
+.hero h1, .detail-intro h1, .message-page h1 { font-family: 'DM Serif Display', Georgia, serif; font-weight: 400; }
+.hero h1 { margin: 22px 0 17px; font-size: clamp(43px, 4.25vw, 68px); line-height: 1.07; letter-spacing: -.035em; }
+.hero h1 em { color: #e1af8b; font-weight: 400; }
+.hero-description { max-width: 450px; margin-bottom: 26px; color: #d5ddd2; font-size: 14px; line-height: 1.85; }
+.hero-link { display: inline-flex; align-items: center; gap: 15px; padding-bottom: 5px; border-bottom: 1px solid #d7a37e; color: #f4dbbd; font-size: 12px; font-weight: 700; }
+.hero-link:hover { color: #fff; }
+.hero-art { position: relative; min-height: 405px; }
+.art-halo { position: absolute; width: 395px; height: 395px; left: 12%; top: 13%; border: 1px solid #ffffff24; border-radius: 50%; box-shadow: 0 0 0 46px #ffffff08, 0 0 0 105px #ffffff05; }
+.art-page { position: absolute; width: 219px; height: 300px; left: 33%; top: 67px; border-radius: 3px 9px 9px 3px; box-shadow: 18px 20px 28px #142d2866; }
+.art-page-back { transform: rotate(13deg) translate(25px, -6px); background: #a9674e; box-shadow: 9px 15px 20px #142d2844; }
+.art-page-front { display: flex; flex-direction: column; align-items: center; padding: 36px 24px 29px; transform: rotate(-8deg); background: #e8ddc5; color: #355045; border-left: 12px solid #d4c6a8; }
+.art-star { font-size: 52px; line-height: 1; font-weight: 400; }
+.art-lines { display: flex; flex-direction: column; align-items: center; gap: 13px; width: 100%; margin-top: 34px; }
+.art-lines i { display: block; width: 84%; height: 2px; background: #9ea994; }
+.art-lines i:nth-child(2) { width: 67%; }
+.art-lines i:nth-child(3) { width: 77%; }
+.art-lines i:nth-child(4) { width: 45%; }
+.art-bottom { margin-top: auto; font-size: 8px; font-weight: 700; letter-spacing: .22em; }
+.art-spark { position: absolute; color: #e5bf91; }
+.art-spark-one { top: 62px; right: 19%; font-size: 28px; }
+.art-spark-two { bottom: 59px; left: 19%; font-size: 28px; }
+
+.library-overview { display: flex; align-items: center; justify-content: space-between; min-height: 79px; margin: 19px 0 58px; padding: 18px 28px; border: 1px solid #e9e5dc; border-radius: 7px; background: #fffefa; }
+.overview-label { color: #917c6b; font-size: 10px; font-weight: 700; letter-spacing: .18em; }
+.overview-stats { display: flex; align-items: center; gap: 21px; color: #647269; font-size: 12px; }
+.overview-stats strong { margin-right: 5px; color: #283e34; font-family: 'DM Serif Display', Georgia, serif; font-size: 24px; font-weight: 400; vertical-align: -2px; }
+.stat-divider { width: 1px; height: 24px; background: #dedfd4; }
+.main-grid { display: grid; grid-template-columns: minmax(0, 1fr) 338px; gap: 48px; align-items: start; padding-bottom: 85px; }
+.shelf { scroll-margin-top: 30px; }
+.finished-shelf { margin-top: 65px; }
+.section-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 23px; padding-bottom: 17px; border-bottom: 1px solid #dfddd3; }
+.section-heading h2 { display: flex; align-items: center; gap: 13px; margin: 6px 0 0; font: 35px/1.15 'DM Serif Display', Georgia, serif; letter-spacing: -.025em; }
+.heading-count { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; border: 1px solid #dadfd4; border-radius: 50%; color: #637467; font: 11px/1 'DM Sans', Arial, sans-serif; letter-spacing: 0; }
+.heading-decoration { color: #bf8d6f; font-size: 22px; }
+.book-list { display: grid; gap: 12px; }
+.empty-state { display: flex; align-items: center; gap: 24px; min-height: 171px; padding: 30px; border: 1px dashed #dcd7c9; border-radius: 7px; background: #fdfbf6; }
+.empty-icon { display: grid; flex: 0 0 76px; place-items: center; width: 76px; height: 85px; border-radius: 2px 7px 7px 2px; background: #e6e9dd; border-left: 6px solid #c9d2c3; box-shadow: 7px 7px 0 #f1eee5; color: #7d9b81; transform: rotate(-5deg); }
+.empty-icon span { font: 35px/1 Georgia, serif; }
+.empty-state h3 { margin-bottom: 6px; font: 20px/1.25 'DM Serif Display', Georgia, serif; }
+.empty-state p { max-width: 380px; margin-bottom: 13px; color: #79857c; font-size: 12px; line-height: 1.65; }
+.finished-empty { min-height: 136px; }
+.finished-empty .empty-icon { height: 66px; background: #eee8df; border-color: #dfd4c4; color: #b69577; }
+.finished-empty p { margin: 0; }
+.text-link { display: inline-flex; align-items: center; gap: 7px; color: #a86c4f; font-size: 11px; font-weight: 700; }
+.text-link:hover { text-decoration: underline; text-underline-offset: 4px; }
+
+.add-panel { position: sticky; top: 24px; scroll-margin-top: 24px; padding: 28px; border: 1px solid #d9e0d4; border-radius: 8px; background: #eaf0e8; }
+.panel-top { display: flex; align-items: center; gap: 11px; }
+.panel-top .eyebrow { color: #6a8271; }
+.panel-icon { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: #d5e1d2; color: #3b6047; font-size: 22px; line-height: 1; }
+.add-panel h2 { margin: 17px 0 4px; font: 35px/1.1 'DM Serif Display', Georgia, serif; letter-spacing: -.035em; }
+.panel-description { margin-bottom: 28px; color: #6c8172; font-size: 12px; line-height: 1.6; }
+.book-form { display: flex; flex-direction: column; }
+.book-form label { display: flex; align-items: center; justify-content: space-between; margin: 0 0 8px; font-size: 11px; font-weight: 700; }
+.book-form label > span:not(.optional) { margin-right: auto; margin-left: 4px; color: #bb7654; }
+.optional { color: #96a598; font-size: 9px; font-weight: 700; letter-spacing: .07em; }
+.book-form input, .book-form textarea { width: 100%; margin-bottom: 20px; padding: 12px 13px; border: 1px solid #dbe2d8; border-radius: 4px; outline: none; background: #fffefa; color: #263b31; font-size: 12px; transition: border-color .2s, box-shadow .2s; }
+.book-form input { height: 42px; }
+.book-form textarea { min-height: 117px; margin-bottom: 0; resize: vertical; line-height: 1.55; }
+.book-form input::placeholder, .book-form textarea::placeholder { color: #a6afa4; }
+.book-form input:focus, .book-form textarea:focus { border-color: #719279; box-shadow: 0 0 0 3px #71927924; }
+.field-hint { margin: 9px 0 20px; color: #7b8c7e; font-size: 10px; line-height: 1.5; }
+.submit-button { display: inline-flex; align-items: center; justify-content: space-between; gap: 15px; width: 100%; min-height: 45px; padding: 12px 16px; border: 1px solid #233b32; border-radius: 4px; background: #233b32; color: #fffdf7; font-size: 12px; font-weight: 700; transition: background .2s, transform .2s; }
+.submit-button:hover { background: #3c604a; transform: translateY(-2px); }
+.submit-button span { font-size: 16px; font-weight: 400; }
+.panel-footer { display: flex; align-items: center; gap: 9px; margin-top: 23px; padding-top: 18px; border-top: 1px solid #d3ded1; color: #788b79; font-size: 10px; }
+.panel-footer span { color: #8f9f8d; font-size: 17px; }
+.form-error { padding: 10px 12px; border: 1px solid #e4c2b2; border-radius: 4px; background: #fff7f1; color: #a74832; font-size: 12px; line-height: 1.5; }
+
+.book-card { display: flex; gap: 22px; min-height: 198px; padding: 17px; border: 1px solid #e6e3d9; border-radius: 7px; background: #fffefa; transition: box-shadow .2s, transform .2s; }
+.book-card:hover { transform: translateY(-2px); box-shadow: 0 9px 22px #25392d0b; }
+.cover-link { flex: 0 0 auto; }
+.book-cover { display: flex; flex-direction: column; width: 114px; height: 162px; overflow: hidden; padding: 14px 13px 12px; border-radius: 2px 5px 5px 2px; border-left: 6px solid #0002; box-shadow: 3px 5px 9px #24342a24; background: #a86851; color: #fff9e9; }
+.book-cover.pine { background: #496e5b; }
+.book-cover.blue { background: #597889; }
+.book-cover.ochre { background: #bd9559; }
+.book-cover.plum { background: #796875; }
+.cover-ornament { margin-left: auto; font: 17px/1 Georgia, serif; opacity: .85; }
+.cover-title { display: -webkit-box; overflow: hidden; margin-top: auto; font: 16px/1.1 'DM Serif Display', Georgia, serif; letter-spacing: -.015em; overflow-wrap: anywhere; -webkit-line-clamp: 4; -webkit-box-orient: vertical; }
+.cover-rule { width: 30px; height: 1px; margin: 11px 0 8px; background: #fff9e9a6; }
+.cover-author { overflow: hidden; font-size: 7px; font-weight: 700; letter-spacing: .06em; text-overflow: ellipsis; text-transform: uppercase; white-space: nowrap; }
+.book-card-content { display: flex; flex: 1; flex-direction: column; min-width: 0; padding: 4px 3px 1px 0; }
+.book-card-top { display: flex; align-items: center; gap: 6px; }
+.status-dot { display: inline-block; flex: 0 0 auto; width: 7px; height: 7px; border-radius: 50%; background: #99ac7a; }
+.status-dot.finished { background: #cb9874; }
+.card-status { color: #778a77; font-size: 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
+.book-card h3 { overflow-wrap: anywhere; margin: 10px 0 4px; font: 23px/1.1 'DM Serif Display', Georgia, serif; letter-spacing: -.02em; }
+.book-card h3 a:hover { color: #ad7457; }
+.byline { margin: 0; color: #7d877a; font-size: 11px; }
+.note-preview { display: -webkit-box; overflow: hidden; margin: 11px 0 0; color: #788279; font-size: 11px; line-height: 1.45; white-space: pre-line; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
+.card-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 10px 21px; margin-top: auto; padding-top: 12px; }
+.finish-link { padding: 0; border: 0; background: none; color: #6c846f; font-size: 11px; font-weight: 700; }
+.finish-link:hover { text-decoration: underline; text-underline-offset: 4px; }
+.finish-link span { margin-left: 3px; }
+
+.site-footer { display: flex; justify-content: space-between; align-items: center; padding: 25px 0 32px; border-top: 1px solid #e4e1d8; color: #8b9588; font-size: 11px; }
+.site-footer > span:first-child { color: #3a4c40; font: 22px/1 'DM Serif Display', Georgia, serif; letter-spacing: -.05em; }
+
+.detail-wrap { max-width: 1080px; min-height: calc(100vh - 183px); margin: 0 auto; padding: 28px 0 80px; }
+.breadcrumb { display: flex; gap: 12px; overflow: hidden; color: #92978b; font-size: 11px; white-space: nowrap; }
+.breadcrumb a { color: #54695a; }
+.breadcrumb a:hover { text-decoration: underline; }
+.breadcrumb span:last-child { overflow: hidden; text-overflow: ellipsis; }
+.back-link { display: inline-block; margin: 34px 0 21px; color: #4c6654; font-size: 11px; font-weight: 700; }
+.back-link:hover { color: #a46c50; }
+.detail-hero { display: grid; grid-template-columns: 340px minmax(0, 1fr); align-items: center; gap: 66px; min-height: 410px; padding: 46px 74px; border-radius: 9px; background: #e9eee6; }
+.detail-cover-wrap { display: flex; justify-content: center; }
+.large-cover { width: 231px; height: 316px; padding: 25px 24px 22px; border-left-width: 12px; box-shadow: 13px 17px 22px #29413633; }
+.large-cover .cover-ornament { font-size: 31px; }
+.large-cover .cover-title { font-size: 31px; }
+.large-cover .cover-rule { width: 50px; margin: 20px 0 15px; }
+.large-cover .cover-author { font-size: 10px; }
+.detail-intro { min-width: 0; }
+.detail-intro .eyebrow { color: #779078; }
+.detail-intro h1 { overflow-wrap: anywhere; margin: 16px 0 9px; font-size: clamp(42px, 5vw, 67px); line-height: 1.05; letter-spacing: -.035em; }
+.detail-author { margin-bottom: 27px; color: #6b8071; font-size: 17px; }
+.detail-status { display: inline-flex; align-items: center; gap: 9px; padding: 10px 13px; border: 1px solid #d0dacc; border-radius: 4px; color: #59715e; font-size: 11px; font-weight: 700; }
+.detail-finish { width: auto; min-width: 187px; margin-top: 30px; }
+.notes-section { margin-top: 65px; }
+.notes-card { min-height: 140px; padding: 30px 34px; border: 1px solid #e6e3d9; border-radius: 7px; background: #fffefa; }
+.notes-card p { max-width: 780px; margin: 0; color: #3e4e43; font: 19px/1.8 'DM Serif Display', Georgia, serif; white-space: pre-wrap; overflow-wrap: anywhere; }
+.notes-card .no-notes { color: #8c988a; font-family: 'DM Sans', Arial, sans-serif; font-size: 13px; }
+.detail-bottom { display: flex; justify-content: space-between; gap: 20px; margin-top: 32px; color: #858f82; font-size: 11px; line-height: 1.6; }
+.detail-bottom a { flex: 0 0 auto; color: #a66b50; font-weight: 700; }
+.detail-bottom a:hover { text-decoration: underline; }
+.message-page { max-width: 600px; min-height: calc(100vh - 182px); margin: 0 auto; padding: 145px 0; text-align: center; }
+.message-page h1 { margin: 14px 0; font-size: 56px; }
+.message-page > p:not(.eyebrow) { color: #758176; font-size: 14px; line-height: 1.7; }
+.message-page .submit-button { width: fit-content; margin-top: 22px; }
+
+@media (max-width: 1080px) {
+  .site-shell { padding: 0 32px; }
+  .main-grid { grid-template-columns: minmax(0, 1fr) 310px; gap: 26px; }
+  .hero-content { padding-left: 47px; }
+  .detail-hero { gap: 30px; padding: 40px; }
+}
+
+@media (max-width: 760px) {
+  .site-shell { padding: 0 20px; }
+  .site-header { height: 76px; }
+  .brand { font-size: 28px; }
+  .top-nav { gap: 15px; }
+  .hero { grid-template-columns: 1fr; min-height: 0; }
+  .hero-content { padding: 48px 36px 42px; }
+  .hero h1 { font-size: clamp(43px, 8vw, 61px); }
+  .hero-art { display: none; }
+  .library-overview { margin-bottom: 44px; }
+  .main-grid { grid-template-columns: 1fr; gap: 48px; }
+  .add-panel { position: static; max-width: 550px; }
+  .detail-hero { grid-template-columns: 240px minmax(0, 1fr); gap: 20px; padding: 35px 24px; }
+  .large-cover { width: 177px; height: 245px; }
+  .large-cover .cover-title { font-size: 24px; }
+  .detail-intro h1 { font-size: 43px; }
+}
+
+@media (max-width: 530px) {
+  .site-shell { padding: 0 15px; }
+  .site-header { height: 69px; }
+  .brand { gap: 8px; font-size: 25px; }
+  .brand-mark { width: 26px; height: 26px; padding: 5px 3px; }
+  .top-nav > a:first-child { display: none; }
+  .nav-add { padding: 10px 11px; font-size: 11px; }
+  .hero { margin-top: 15px; }
+  .hero-content { padding: 42px 26px; }
+  .hero h1 { font-size: clamp(39px, 10vw, 50px); }
+  .hero-description { font-size: 13px; }
+  .library-overview { align-items: flex-start; flex-direction: column; gap: 11px; padding: 18px 20px; }
+  .overview-stats { gap: 14px; }
+  .section-heading h2 { font-size: 30px; }
+  .empty-state { align-items: flex-start; gap: 20px; padding: 23px 18px; }
+  .empty-icon { flex-basis: 54px; width: 54px; height: 68px; }
+  .empty-state h3 { font-size: 18px; }
+  .book-card { gap: 15px; padding: 13px; }
+  .book-cover { width: 86px; height: 130px; padding: 10px 9px; }
+  .cover-title { font-size: 13px; }
+  .cover-author { font-size: 6px; }
+  .book-card h3 { font-size: 19px; }
+  .book-card-content { padding-top: 0; }
+  .card-actions { gap: 8px 13px; }
+  .detail-wrap { padding-top: 20px; }
+  .back-link { margin: 27px 0 18px; }
+  .detail-hero { grid-template-columns: 1fr; gap: 32px; padding: 38px 27px; }
+  .large-cover { width: 186px; height: 255px; }
+  .detail-intro h1 { font-size: 44px; }
+  .notes-section { margin-top: 46px; }
+  .notes-card { padding: 24px; }
+  .detail-bottom { flex-direction: column; }
+  .site-footer { gap: 12px; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  html { scroll-behavior: auto; }
+  *, *::before, *::after { transition-duration: .01ms "'!important; animation-duration: .01ms !important; }
+}
*** End Patch
PATCH
npm run build'

